# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_29_369_2", r"в условии потеряна десятичная запятая: $a_{22}=-5{,}5$ (дистракторы и ключ считают $d=4{,}5$: $a_{1}=-10-20\cdot4{,}5=-100$); при $a_{22}=-5$ получилось бы $a_{1}=-110$",
  q=r"Найдите первый член арифметической прогрессии, если: $a_{21} = -10$, $a_{22} = -5{,}5$.")
E("G9_TB_29_586_a", r"$d=18{,}3-20{,}7=-2{,}4$; $20{,}7-2{,}4(n-1)=-1{,}3\Rightarrow n-1=\frac{22}{2{,}4}=9\frac16$ — не целое, число $-1{,}3$ членом прогрессии не является; (для $-3{,}3$: $n-1=10$, да). В ключе стояло «да»",
  k=r"нет",
  dnew={0: (r"да", r"Ученик принял число $9\frac16$ за номер члена (или округлил до целого): номер $n=1+\frac{22}{2{,}4}$ должен быть натуральным, а здесь он не целый."),
        1: (r"да, это $9$-й член", r"Ученик допустил арифметическую ошибку при решении уравнения $20{,}7-2{,}4(n-1)=-1{,}3$ и получил целое $n=9$; проверка: $a_{9}=20{,}7-19{,}2=1{,}5\ne-1{,}3$."),
        2: (r"да, это $10$-й член", r"Ученик округлил $9\frac16$ до $10$; но $a_{10}=20{,}7-21{,}6=-0{,}9\ne-1{,}3$, число членом прогрессии не является.")})
E("G9_TB_29_594_3", r"$q=\frac{-32/3}{64/9}=-\frac32$; $b_{6}=\frac{64}{9}\cdot\left(-\frac32\right)^{5}=\frac{64}{9}\cdot\left(-\frac{243}{32}\right)=-54$ (в ключе $-243$)",
  k=r"$b_{6} = -54, b_{n} = \dfrac{64}{9} \cdot \left(-\dfrac{3}{2}\right)^{n-1}$",
  dnew={0: (r"$b_{6} = 81, b_{n} = \dfrac{64}{9} \cdot \left(-\dfrac{3}{2}\right)^{n}$", r"Ученик в формуле общего члена использовал показатель $n$ вместо $n-1$: $b_{6}=\frac{64}{9}\left(-\frac32\right)^{6}=81$; верно $b_{6}=b_{1}q^{5}=-54$."),
        1: (r"$b_{6} = 54, b_{n} = \dfrac{64}{9} \cdot \left(\dfrac{3}{2}\right)^{n-1}$", r"Ученик при делении $b_{2}$ на $b_{1}$ потерял знак минус и взял $q=\frac32$."),
        2: (r"$b_{6} = -\dfrac{243}{32}, b_{n} = \dfrac{64}{9} \cdot \left(-\dfrac{3}{2}\right)^{n-1}$", r"Ученик записал верную формулу, но при вычислении $b_{6}$ вычислил только $q^{5}=-\frac{243}{32}$, не умножив на $b_{1}=\frac{64}{9}$.")})
